from pytz import timezone

def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    if nanoseconds is None:
        raise ValueError("nanoseconds cannot be None")

    if tz is None:
        tz = timezone.utc  # Default to UTC if no timezone is provided

    # Convert nanoseconds to a datetime object
    timestamp = datetime.fromtimestamp(nanoseconds / 10**9, tz=tz)

    # Wrap the datetime object in the appropriate type
    if isinstance(nanoseconds, int) and isinstance(tz, int):
        return datetime.datetime.fromtimestamp(nanoseconds / 10**9, tz=timezone(tz))
    else:
        return timezone(tz).localize(timestamp)

