def xargs(cmd: tuple[str, ...], varargs: Sequence[str], *, color: bool = False, target_concurrency: int = 1, _max_length: int = _get_platform_max_length(), **kwargs: Any) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    if isinstance(cmd, str):
        cmd = (cmd,)

    result = [['0']] * len(cmd)
    for i, arg in enumerate(cmd):
        if not i == 0:
            result[i].append(' ')
        result[i].append(arg + ' ')

    result_str = ''.join(' '.join(text) + '\n' for text in result)

    # Use subprocess.Popen for parallel processing
    if color:
        import subprocess
        ret = subprocess.Popen(['xargs', '-t', str(target_concurrency)], input=result_str, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    else:
        ret = subprocess.Popen(['xargs', '-t'], input=result_str, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

    stdout, stderr = ret.communicate()
    if ret.returncode != 0:
        raise subprocess.CalledProcessError(ret.returncode, ret.stdout, ret.stderr)

    return ret.returncode, stdout if not color else stderr

