def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """
    Fixes for the following issues on Windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    normalized_cmd = []
    for arg in cmd:
        if arg.startswith('#!'):
            # we only need to consider the first one
            if not normalized_cmd:
                # convert the first shebang to a utf-8 encoded string
                normalized_cmd.append(bytearray.fromhex(arg.replace('#!', 'f0fd0a')), 'utf-8')
            else:
                # append any subsequent shebangs to the normalized command ignoring
                # the first one
                normalized_cmd.append(bytearray.fromhex(arg.replace('#!', 'f0fd0a')))
        else:
            normalized_cmd.append(arg)
    return tuple(normalized_cmd)

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    if sys.platform == 'win32':
        # Ensure shebang is correctly parsed on Windows
        for i, part in enumerate(cmd):
            if part.startswith('#!'):
                cmd[i] = part.replace('\\', '\\\\')
    return cmd

