import time

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """

    def _ttl_cache(func):
        cache = {}

        def memoised_func(*args, **kwargs):
            time_key = timer()
            if args in cache and time_key - cache[args][0] > ttl:
                del cache[args]
            elif args not in cache or cache[args][1] < ttl_key:
                cache[args] = (time_key, func(*args, **kwargs))

            return cache[args][1]

        return memoised_func

    return _ttl_cache

