def extostr(e, max_level=30, max_path_level=5):
    """Format an exception.

    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """

    def get_recursive_message(e, indent=0):
        frames = traceback.extract_tb(e.__traceback__)
        if max_level > 0:
            max_level -= 1
        else:
            return

        messages = []

        for frame in frames:
            if max_path_level > 0:
                max_path_level -= 1
            else:
                break

            file_path, line_number, function_name, lines, line_index = frame

            callstr = f"{function_name} at line {line_number} ({file_path})"
            arrow = "    " * indent + "│"
            messages.append(f"{arrow} {callstr}")

            if lines:
                line_content = lines[line_index]
                if " self" in line_content:
                    contents = line_content[:line_content.find(" self")]
                else:
                    contents = line_content

                for i, line in enumerate(contents.splitlines()):
                    if i > 0 and (i % 80 == 0 or i == len(contents) - 1):
                        messages.append(f"{arrow} {line}")
                        messages.append("    " * (indent + 1) + "│")
                    else:
                        messages.append(f"{arrow} {line: <80}")

                if hasattr(e, "extra"):
                    extra = "\nExtra:\n\n" + e.extra
                else:
                    extra = ""

                lines_with_extra = contents.splitlines() + [""] * 8 if len(contents.splitlines()) % 2 == 1 else contents.splitlines()
                length = len(lines_with_extra)
                for i, line in enumerate(lines_with_extra):
                    if i == int(length / 2):
                        messages.append(f"{arrow} {line + extra}")
                        break
                return

        return "\n".join(messages)

    if not isinstance(e, Exception):
        return str(e)

    messages = ["Exception: " + str(e)]

    if not e.args:
        return "\n".join(messages)

    message = " Info: {0}".format(e.args[0]) if len(e.args) > 0 else ""
    messages.append(message)

    stack_trace = get_recursive_message(e)
    if stack_trace:
        messages.append("\nStack trace:")
        messages.append(stack_trace)

    return "\n".join(messages)

