def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    for cls in classes:
        seen.add(cls)
        while cls in cls.ancestors:
            cls = cls.ancestors[0]
            if cls in seen:
                break
            seen.add(cls)
    return.sorted(seen)

