from typing import Any, Dict, List, Union

class Point:
    def __init__(self, coordinate: List[float], value: Dict[str, Any]):
        self.coordinate = coordinate
        self.value = value

    def to_csv_string(self, separator: str) -> str:
        return separator.join(map(str, self.coordinate)

    def __str__(self) -> str:
        return self.to_csv_string(separator)

class Graph:
    def __init__(self, points: List[Point]):
        self.points = points

    def to_csv(self, separator: str = ",", header: str = None) -> str:
        """Convert graph's points to CSV.

        Parameters:
            separator (str): Delimits values, the default is comma.
            header (str): If not None, is the first string of the output (new line is added automatically).

        Since a graph can be multidimensional,
        for each point first its coordinate is converted to string
        (separated by *separator*), then each part of its value.

        To convert :class:`Graph` to CSV inside a Lena sequence,
        use :class:`lena.output.ToCSV`.
        """
        if header:
            output = header + "\n"
        else:
            output = ""

        for point in self.points:
            values = [str(value) for value in point.value.values()]
            output += point.to_csv_string(separator) + separator + " ".join(values) + "\n"

        return output

