            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for observed, kubernetes in observer_schema.items():
        if observed in response:
            if not kubernetes:
                last_applied_manifest[observed] = response[observed]
            elif isinstance(response[observed], (dict, list, str, int)):
                if observed in last_applied_manifest:
                    if not isinstance(last_applied_manifest[observed], type(response[observed])):
                        raise ValueError(f"Type mismatch for observed field {observed}. Expected {type(response[observed])}, got {type(last_applied_manifest[observed])}")
                    else:
                        last_applied_manifest[observed].update(response[observed])
                else:
                    last_applied_manifest[observed] = response[observed]
            elif observed in last_applied_manifest:
                if not isinstance(last_applied_manifest[observed], list):
                    raise ValueError(f"Type mismatch for observed field {observed}. Expected list, got {type(last_applied_manifest[observed])}")
                last_applied_manifest[observed] += response[observed]
    for observed in observer_schema:
        if observed not in last_applied_manifest:
            last_applied_manifest[observed] = response[observer_schema[observed]]

