def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    import json

    # extract manifest URLs from application spec
    manifest_urls = [resource['url'] for resource in app.spec.manifest]

    # define default observer schemas
    default_schemas = {
        # example: "https://example.com/v1/resource"
        "v1/persistentvolumeclaim": {
            "type": "object",
            "properties": {
                "metadata": {
                    "type": "object",
                    "properties": {
                        "name": {
                            "type": "string"
                        },
                        "namespace": {
                            "type": "string",
                            "description": "Namespace where the PVC is located"
                        }
                    },
                    "required": ["name", "namespace"]
                },
                "spec": {
                    "type": "object",
                    "properties": {
                        "accessModes": {
                            "type": "array",
                            "items": {
                                "type": "string"
                            }
                        },
                        "resources": {
                            "type": "object",
                            "properties": {
                                "requests": {
                                    "type": "object",
                                    "properties": {
                                        "storage": {
                                            "type": "string"
                                        }
                                    },
                                    "required": ["storage"]
                                }
                            },
                            "required": ["requests"]
                        }
                    },
                    "required": ["accessModes", "resources"]
                }
            },
            "required": ["metadata", "spec"]
        },
        # example: "https://example.com/v1/persistentvolume"
        "v1/persistentvolume": {
            "type": "object",
            "properties": {
                "metadata": {
                    "type": "object",
                    "properties": {
                        "name": {
                            "type": "string"
                        },
                        "namespace": {
                            "type": "string",
                            "description": "Namespace where the PVC is located"
                        }
                    },
                    "required": ["name", "namespace"]
                },
                "spec": {
                    "type": "object",
                    "properties": {
                        "capacity": {
                            "type": "object",
                            "properties": {
                                "storage": {
                                    "type": "string"
                                }
                            },
                            "required": ["storage"]
                        },
                        "accessModes": {
                            "type": "array",
                            "items": {
                                "type": "string"
                            }
                        }
                    },
                    "required": ["capacity", "accessModes"]
                }
            },
            "required": ["metadata", "spec"]
        }
    }

    # generate default observer schema for each manifest
    for manifest_url in manifest_urls:
        schema_name = manifest_url.split('/')[-2]

        if schema_name in default_schemas:
            continue

        # get manifest content
        response = app.kube_client.get(self.URI + resource, format='json')
        manifest = json.loads(response.text)

        # add default observer schema for this manifest
        default_schemas[schema_name] = manifest

        # save default observer schema to file
        with open("default_observer_schemas/" + schema_name + ".json", "w+") as f:
            f.write(json.dumps(default_schemas[schema_name], indent=4))

        print("Generated default observer schema for " + schema_name + " from " + manifest_url)

