def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    if not app.spec.manifest:
        raise ValueError("Missing manifest in the application specification.")

    default_schemas = defaultdict(dict)
    for resource in app.spec.manifest:
        if not resource.spec:
            raise ValueError(f"Missing spec in resource {resource.kind}.")

        if not resource.spec.observers:
            raise ValueError(f"Missing observers in resource {resource.kind}.")

        for observer in resource.spec.observers:
            schema_name = observer.schema
            if schema_name in default_schemas[resource.kind]:
                raise ValueError(f"Duplicate schema name {schema_name} in resource {resource.kind}.")
            default_schemas[resource.kind][schema_name] = {
                "apiVersion": "openapi3"
            }

    return default_schemas

