def format(self, sql, params):
        """
        Convert the SQL query to use the out-style parameters instead of
        the in-style parameters.

        *sql* (:class:`str` or :class:`bytes`) is the SQL query.

        *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
        *params* must be a :class:`~collections.abc.Sequence`.

        Returns a :class:`tuple` containing:

        -	The formatted SQL query (:class:`str` or :class:`bytes`).

        -	The set of converted out-style parameters (:class:`dict` or
            :class:`list`).
        """
        quoted_params = []

        if isinstance(sql, bytes):
            string_sql = sql
            ready_params = params

        elif isinstance(sql, str):
            string_sql = sql.encode('utf-8')
            ready_params = params

        else:
            raise TypeError("Parameter 'sql' must be a str or bytes")

        placeholders = ','.join(
            (OpValueParameter.param_name(special=True) if isinstance(s, SpecialParameter) else "%s") for s in string_sql)

        if isinstance(params, dict):
            for key, value in params.items():
                if isinstance(key, SpecialParameter):
                    quoted_params.append(OpValueParameter(param_name(special=True) inplaces=True).new(sql, placeholders, special=True))
                else:
                    quoted_params.append(ValueParameter(param_name(key)).new(sql, placeholders, special=False))

        elif isinstance(params, Sequence):
            for key, value in enumerate(params):
                if isinstance(key, SpecialParameter):
                    quoted_params.append(OpValueParameter(param_name(special=True) inplaces=True).new(sql, placeholders, special=True))
                else:
                    quoted_params.append(ValueParameter(param_name(key)).new(sql, placeholders, special=False))

        else:
            raise TypeError("Parameter 'params' must be a dict or sequence")

        return string_sql, tuple(quoted_params)

def format(self, sql, params):
        """
        Convert the SQL query to use the out-style parameters instead of
        the in-style parameters.

        *sql* (:class:`str` or :class:`bytes`) is the SQL query.

        *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. If :attr:`.SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
        *params* must be a :class:`~collections.abc.Sequence`.

        Returns a :class:`tuple` containing:

        -	The formatted SQL query (:class:`str` or :class:`bytes`).

        -	The set of converted out-style parameters (:class:`dict` or
            :class:`list`).
        """
        if type(sql) is str:
            sql = sql.encode('latin-1')

        if type(params) is dict:
            sql = sql.replace('%s', '{}')
            return (sql, list(params.values()))

        if type(params) is list:
            for i in range(len(params)):
                if isinstance(params[i], int) or isinstance(params[i], float):
                    params[i] = '%f' % params[i]
                elif isinstance(params[i], str):
                    params[i] = f'%s' % params[i]
            sql = sql.replace('%s', '?')
            return (sql, params)

        raise ValueError('Invalid input type for params')

