def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    for file_path in manifest_files:
        if os.path.exists(file_path)):
            file_stat = os.stat(file_path)
            file_mtime = file_stat.st_mtime
            for digest in digests_used:
                digest_path = digest + '.sha256'
                if os.path.exists(digest_path):
                    digest_stat = os.path.getmtime(digest_path)
                    if digest_path != os.path.join(os.path.dirname(file_path), digest_path):
                        print(f"Digest mismatch for file {file_path}: digest_path {digest_path} does not match file_new's digest path {digest} (mtime diff: {digest_stat - file_mtime}).")
                    elif digest_stat == file_mtime:
                        print(f"Digest Ok for file {file_path}")
                    else:
                        print(f"Digest older for file {file_path}: digest_path {digest_path} has a timestamp of {digest_stat}, while file's timestamp is {file_mtime}")

