def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_paths_map = {}
    for mapping in inventory.logical_paths:
        if mapping.version == version:
            logical_paths_map[mapping.logical_path] = set(mapping.content_files)
    return logical_paths_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}

    for entity in inventory:
        if entity.get_version() == version:
            logical_path = entity.get_logical_path()
            content_files = entity.get_content_files()
            logical_path_map[logical_path] = content_files

    return logical_path_map

def get_logical_path_map(inventory, version):
    file_map = {}

    for filename, inventory_item in version.files.items():
        file_content = join(inventory.directories[filename], inventory_item.path)
        if file_content in file_map:
            file_map[file_content].add(filename)
        else:
            content_files = {filename}
            file_map[file_content] = content_files

    return file_map

