        if manifest_file not in fixity_dict:
            raise ValueError("File not found in manifest: " + manifest_file)

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not fixity:
        raise ValueError("Fixity block cannot be empty.")

    if not isinstance(manifest_files, list) or not all(isinstance(f, str) for f in manifest_files):
        raise ValueError("Manifest files must be a list of strings.")

    # Validate fixity block structure
    section_name = fixity.upper()[0]
    if section_name not in ['FILE', 'IMAGE', 'HARDLINK', 'SYMLINK']:
        raise ValueError(f"Invalid fixity section: {section_name}")

    # Check for duplicates and missing files
    seen_files = set()
    for file_item in fixity.split('\n'):
        file_item = file_item.strip()
        if not file_item:
            continue

        file_parts = file_item.split()
        if len(file_parts) != 2:
            raise ValueError(f"Invalid fixity item: {file_item}")

        file_id, file_path = file_parts
        if file_id in seen_files:
            raise ValueError(f"Duplicate fixity id: {file_id}")
        if not os.path.exists(file_path):
            raise ValueError(f"File not found: {file_path}")

        seen_files.add(file_id)

    # Check included files in manifest
    included_files = [entry.strip() for entry in manifest_files if os.path.exists(entry)]
    missing_files = [file for file in included_files if file not in seen_files]

    if missing_files:
        raise FileNotFoundError(f"Manifest files not present: {', '.join(missing_files)}")

