def validate_version_inventories(self, version_dirs, content_digests=None):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).

    Args:
        version_dirs (list): An array of version directory names
        content_digests (dict or None): A dictionary of content digests different from those in the root inventory
    """
    if content_digests is None:
        content_digests = self.get_content_digests()

    root_digest = self.get_root_digest()

    inventories = self.get_inventories()

    for version_dir in version_dirs:
        if version_dir not in inventories:
            raise VersionNotFoundError("Version directory " + version_dir + " does not exist. Please provide an existing version directory.")
        else:
            current_digest = inventories[version_dir].get digest()
            if current_digest != root_digest:
                if content_digests is not None and current_digest not in content_digests:
                    raise ContentDigestMismatchError("Content digest for version directory " + version_dir + " (" + current_digest + ") does not match content digest for root inventory (" + root_digest + "). Please verify content digest in root inventory before validating.")
                raise InventoryVersionMismatchError("Version directory " + version_dir + " has a different content digest than the root inventory (" + root_digest + "). Please verify content digest in root inventory before validating.")

