def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*Supplier" Namaste files to determine the directory type.
    """
    if not path.startswith('/'):
        return "error path not starts with a leading slash"

    try:
        if path[0] == '/' and path[1] == '*':
            # check for and possibly identify a root目录 or object
            if path[2:] == 'Supplier':
                return 'root' # guess it's a root directory
            else:
                # check if the path looks like an object
                obj_id = path[3:]
                if obj_id.isdigit():
                    return 'object'
                else:
                    return "error path not forms a valid object id"
        else:
            if path[0] == '*' and path[1:] == 'Developer':
                return 'object' # could be any object with the Developer set
            else:
                return "unknown path type"
    except IndexError:
        return "error invalid path length"

