def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000

    Raises:
        ValueError: If input size is not a valid string
    """
    if not isinstance(size, str):
        raise ValueError("Input size must be a string")

    size_units = {
        unit: pow(10, order) for order, unit in zip([0, 3, 6, 9, 12, 15, 18], ['B', 'KB', 'MB', 'GB', 'TB', 'PB', 'EB'])
    }

    units = 'BKMGTPEZY'
    unit_none = '?'
    unit_int = chr(1073741824)

    if not any(unit in size for unit in units):
        if unit_none in size:
            return None
        elif unit_int in size:
            return int(size)
        else:
            raise ValueError("Invalid size format")

    for unit in size[::-1]:
        if unit in units:
            value = int(size[:-1])
            return round(value * size_units[unit], 6)
    return 0

