def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet or not alphabet:
        raise ValueError("Both alphabet and number must be provided")
    if number % len(alphabet) != 0:
        if padding is None:
            raise ValueError("Number does not fit into the alphabet and no padding was specified")
        number += len(alphabet) * (padding // len(alphabet) + 1)
    digits = []
    while number > 0:
        digit = number % len(alphabet)
        digits.append(alphabet[digit])
        number //= len(alphabet)
    digits.reverse()
    if padding is None:
        return ''.join(digits)
    else:
        return digits.rjust(padding, alphabet[0])

