def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    platform = {'this': None, 'posix': 1, 'windows': 0}[platform]
    if platform == 1:
        ESCAPES = re.compile(r'([`)\\s]+)')
    elif platform == 0:
        ESCAPES = re.compile(r'("|\'|\\s+[`\\s]+\'')', re.IGNORECASE)
    else:
        raise ValueError('Invalid value for platform')

    parts = []
    last_end = 0
    for match in ESCAPES.finditer(s):
        begin = match.start()
        if last_end < begin:
            parts.append(s[last_end:begin])
        escape = match.group()
        if len(escape) == 3 or escape[-1].isalnum():
            last_end = match.start() + 2
        else:
            last_end = match.start() + 1
        if begin == last_end:
