import shutil
from pathlib import Path

def prepare_repository_from_archive(archive_path: str, filename: Optional[str] = None, tmp_path: Union[Path, str] = "/tmp") -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not filename:
        filename = archive_path.split('/')[-1]
    # decompress archive into temporary directory
    temp_dir = Path(tmp_path) / filename
    if not temp_dir.exists():
        temp_dir.mkdir(parents=True)
    subprocess.run(['tar', '-xzf', archive_path, '-C', temp_dir])

    # If filename is included, return the path to the file inside the archive
    if filename:
        file_path = temp_dir / filename
        return file_path.as_uri()
    else:
        return str(temp_dir)

