def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""

    output = subprocess.check_output(['git', 'diff', '--name-only', '--ignore-untracked-files', '.']).decode('utf-8').split('\n')
    output = [f for f in output if f.endswith(ignored)]
    output.sort()

    return ', '.join(output)

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''

    try:
        output = subprocess.check_output(['git', 'ls-files', '--ignored'], text=True, stderr=subprocess.STDOUT)
    except subprocess.CalledProcessError as e:
        raise RuntimeError("Failed to obtain ignored file list: " + str(e.output))

    file_list = output.strip().split('\n')
    ignored_files = [filename for filename in file_list if filename]
    ignored_files = ','.join(sorted(ignored_files))

    return ignored_files

