    """Dump to a py2-unicode or py3-string"""

    if isinstance(obj, str):
        if dumper is not None:
            return dumper.represent_scalar("tag:yaml.org,2001:str", obj)
        else:
            return obj
    elif isinstance(obj, (bytes, bytearray)):
        if dumper is not None:
            return dumper.represent_scalar("tag:yaml.org,2001:str", obj.decode('utf-8'))
        else:
            return obj.decode('utf-8')
    elif isinstance(obj, (list, tuple, dict)):
        if dumper is not None:
            if dumper.default_flow_style is None:
                dumper.default_flow_style = True
            if not obj:
                return dumper.represent_scalar("tag:yaml.org,2001:str", '[]')
            return dumper.represent_mapping("tag:yaml.org,2001:map", obj)
        else:
            if not obj:
                return '[]'
            if isinstance(obj, list):
                return ','.join(map(_dump_string, obj))
            elif isinstance(obj, tuple):
                return ','.join(map(_dump_string, obj))
            elif isinstance(obj, dict):
                return '{%s}' % ', '.join(['%s: %s' % (_dump_string(key), _dump_string(value)) for key, value in sorted(obj.items())])
    else:
        raise ValueError('unrecognized type: %s' % type(obj))

from dpkt.dumper import Dumper

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    if dumper is None:
        dumper = Dumper(maxident=100)

    def _seqsep(pairs, indent):
        n = len(pairs)
        if n < 2:
            return ''
        else:
            pairs[-1] = '%s %s' % (pairs[-1], pairs[-2])
            del pairs[-2]
            lenextra = (indent * 2) * (n - 1)
            return '%s\n%s%s' % (pairs[0], ' ' * lenextra, pairs[1])
    def _seqobj(entity, indent):
        pairs = [('value', entity.value)]
        return _seqsep(pairs, indent)
    def _seqkey(entity, indent):
        pairs = [('name', entity.name)]
        return _seqsep(pairs, indent)
    def _mapobj(entity, indent):
        pairs = [(_seqobj(e, indent + 4) for e in entity.key] + [_seqobj(e, indent + 4) for e in entity.value])
        return _seqsep(pairs, indent)
    def _iobj(entity, indent):
        pairs = [(_seqobj(e, indent + 4) for e in entity.field)]
        return _seqsep(pairs, indent)
    if isinstance(obj, yaml.ScalarNode):
        yield obj.value
    elif isinstance(obj, yaml.SequenceNode):
        items = obj.value
        for item in items:
            _dump_string(item, dumper)
        if obj.flow_style == yaml.SEPARATED flow_style:
            yield _seqsep(items, 0)
    elif isinstance(obj, yaml.MappingNode):
        items = obj.value.items()
        for key, value in items:
            yield _seqkey(key, 0)
            yield _dump_string(value, dumper)
            yield '\n'
        if obj.flow_style == yaml.SEPARATED flow_style:
            yield '\n'
    elif isinstance(obj, yaml.CommentedScalarNode):
        yield obj.value
        yield '\n'

