from logging import getLogger, LogRecord, makeRecord

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    logger = getLogger("Loader")
    results = {}
    errors = []

    for filename in config_filenames:
        try:
            parsed_config = load_config(filename, overrides, resolve_env)
            results[filename] = parsed_config
        except ImportError as e:
            logger.error(f"Failed to import configuration from {filename}: { str(e)}")
            errors.append(makeRecord("Loader", logging.ERROR, filename, 0, f"Failed to import configuration from {filename}: { str(e)}", 0, None))
        except ValueError as e:
            logger.error(f"Failed to validate configuration from {filename}: { str(e)}")
            errors.append(makeRecord("Loader", logging.ERROR, filename, 0, f"Failed to validate configuration from {filename}: { str(e)}", 0, None))

    return results, errors

