class Time:
    def __init__(self, ticks, tz=None):
        if not (0 <= ticks < 86400000000000):
            raise ValueError("ticks out of bounds (0 <= ticks < 86400000000000)")

        self.ticks = ticks
        self.tz = tz or timezone.utc

    def convert_to_datetime(self):
        # assuming ticks represent the number of seconds since the epoch
        return datetime.utcfromtimestamp(self.ticks / 1000000000)

