def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    if tentative:
        return True

    provided_by = iface.providedBy(candidate)

    if not provided_by:
        raise zope.interface.Invalid("{} does not provide {}".format(candidate, iface))

    methods = iface.getMethods()
    candidate_methods = candidate.__dict__.get("methods", [])

    for method in methods + candidate_methods:
        if method not in candidate_methods or method not in candidate.__methods__:
            raise zope.interface.Invalid("{} does not implement {}".format(candidate, method))

    attributes = iface.getAttributes()
    candidate_attributes = candidate.__dict__.get("attributes", [])

    for attribute in attributes + candidate_attributes:
        if attribute not in candidate_attributes or attribute not in candidate.__attributes__:
            raise zope.interface.Invalid("{} does not provide {}".format(candidate, attribute))

    method_signatures = {method: getattr(candidate, method).__code__.co_argcount
                        for method in candidate_methods}
    candidate_method_signatures = {method: getattr(candidate, method).__code__.co_argcount
                            for method in candidate_methods}

    for method, sig in method_signatures.items():
        if method not in candidate_method_signatures:
            raise zope.interface.Invalid("{} does not implement {} with correct signature".format(candidate, method))
        if sig != candidate_method_signatures[method]:
            raise zope.interface.Invalid("{} does not implement {} with correct signature".format(candidate, method))

    attribute_types = {}
    for attribute, type_ in iface.getAttributes(True).items():
        if attribute not in candidate_attributes:
            raise zope.interface.Invalid("{} does not provide {} with correct type".format(candidate, attribute))
        if type_ != candidate_attributes[attribute]:
            raise zope.interface.Invalid("{} does not provide {} with correct type".format(candidate, attribute))

    for method, sig in candidate_method_signatures.items():
        if method in iface.getMethods():
            if sig != iface.getMethods()[method].__code__.co_argcount:
                raise zope.interface.Invalid("{} does not implement {} with correct signature".format(candidate, method))

    for attribute, type_ in candidate_attributes.items():
        if attribute in iface.getAttributes(True):
            if type_ != iface.getAttributes()[attribute]:
                raise zope.interface.Invalid("{} does not provide {} with correct type".format(candidate, attribute))

    return True

