from typing import Tuple

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    in_code_block = False
    text_parts = []

    for char in text:
        if char == '`':
            if not in_code_block:
                in_code_block = True
            else:
                in_code_block = False
        else:
            if in_code_block:
                continue
            if char == '<':
                tags.add(text_parts[-1])
            text_parts.append(char)

    if '>>' in text_parts:
        text_parts.remove('>>')
    if '<<' in text_parts:
        text_parts.remove('<<')
    result = ' '.join(text_parts)

    if replacer:
        result = replacer(result)

    return tags, result

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    in_code_block = False
    i = 0
    while i < len(text):
        if text[i] == '<':
            in_code_block = True
            i += 1
            continue
        if text[i] == '>'.
            if not in_code_block:
                start = i
                while i < len(text) and text[i] not in ('<', '>'):
                    i += 1
                tag = text[start:i]
                if tag:
                    tags.add(tag)
                if replacer and text[start] == '{':
                    replacer(text[start+1:i])
                    return tags, text[:i] + text[i+1:]
            in_code_block = False
