def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Check if the document is in JSON format
    if document.startswith('{'):
        try:
            parsed = json.loads(document)
        except json.JSONDecodeError:
            return {"Error": "Invalid JSON format"}
    # Check if the document is in XRD format
    elif document.startswith('<?xml'):
        root = ET.fromstring(document)
        parsed = {
            "preferred_username": root.find(".//{http://xmlns.diaspora.org/schemas/diaspora/2008/01}preferred_username").text,
            "public_key": root.find(".//{http://xmlns.diaspora.org/schemas/diaspora/2008/01}public_key").text,
            "website": root.find(".//{http://xmlns.diaspora.org/schemas/diaspora/2008/01}website").text,
            "following": [child.text for child in root.findall(".//{http://xmlns.diaspora.org/schemas/diaspora/2008/01}tagged_as/following")]
        }
    else:
        return {"Error": "Unsupported format"}

    return parsed

