def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active
    workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down
        directly to Ansible.
    """
    import subprocess as sp
    if verbose is None:
        verbose = 0

    args = ['ansible-playbook', playbook_path]
    if verbose:
        args.append('-v')

    if extra_vars:
        args.extend(['--extra-vars', '='.join([s + '="' + v + '"' for s, v in extra_vars.items()])])

    if ansible_args:
        args.extend(list(ansible_args.items()))

    try:
        result = sp.run(args, check=True, capture_output=True)
        if verbose > 1:
            print(result.stdout.decode('utf-8'))
        return result.stdout.decode('utf-8')
    except sp.CalledProcessError as e:
        if verbose:
            print(e.stdout.decode('utf-8'))
            print(e.stderr.decode('utf-8'))
        if e.returncode:
            raise RuntimeError("Ansible failed, exit code: {}".format(e.returncode))

