def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for key, value in values_dict.items():
        try:
            # attempt to convert the value to the appropriate data type
            if key in self.parser_type_mapping:
                if self.parser_type_mapping[key] == int:
                    values_dict[key] = int(value)
                elif self.parser_type_mapping[key] == float:
                    values_dict[key] = float(value)
                elif self.parser_type_mapping[key] == bool:
                    values_dict[key] = value.lower() == 'true' or value.lower() == 'false'
            else:
                values_dict[key] = value
        except ValueError:
            # print the error message in case of conversion failure
            print(f"Failed to convert argument '{key}' with value '{value}' for parser '{parser_name}'.")

